CREATE TABLE ordinary_account_attempts (
  account_id TEXT NOT NULL PRIMARY KEY, attempt_id TEXT NOT NULL
)

CREATE TABLE ordinary_attempts_schema_marker (
  id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL CHECK(version=1)
)

CREATE TABLE siwc_authorization_intents (
      attempt_id TEXT PRIMARY KEY, account_id TEXT NOT NULL
    )

CREATE TABLE siwc_refresh_claim_versions (
      token_fingerprint TEXT PRIMARY KEY, source_revision TEXT NOT NULL
    )
